create table public.push_deliveries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces,device_id uuid not null references public.devices,notification_id bigint not null references public.notifications,status text not null default 'pending',sent_at timestamptz,next_attempt timestamptz not null default now(),error text,unique(device_id,notification_id));
alter table public.push_deliveries enable row level security;
create policy workspace_read on public.push_deliveries for select to authenticated using(workspace_id=public.my_workspace());
create function public.claim_push_jobs() returns table(id uuid,device_id uuid,notification_id bigint,fcm_token text,title text,body text) language plpgsql security definer set search_path='' as $$begin
insert into public.push_deliveries(workspace_id,device_id,notification_id) select n.workspace_id,d.id,n.id from public.notifications n join public.devices d using(workspace_id) where d.revoked_at is null and d.expires_at>now() and d.fcm_token is not null and n.created_at>=d.created_at and n.created_at>now()-interval '1 day' on conflict do nothing;
return query with claimed as(update public.push_deliveries set next_attempt=now()+interval '5 minutes' where push_deliveries.id in(select p.id from public.push_deliveries p where p.status='pending' and p.next_attempt<=now() for update skip locked limit 20) returning *)select p.id,p.device_id,p.notification_id,d.fcm_token,n.title,n.body from claimed p join public.devices d on d.id=p.device_id join public.notifications n on n.id=p.notification_id where d.revoked_at is null and d.expires_at>now() and d.fcm_token is not null;end$$;
revoke all on function public.claim_push_jobs() from public,anon,authenticated;
grant execute on function public.claim_push_jobs() to service_role;
create or replace function public.runtime_secret(p_name text) returns text language sql security definer set search_path='' as $$select decrypted_secret from vault.decrypted_secrets where name='wasl_'||p_name$$;
